import math

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def cos(a, b):
    na = math.sqrt(dot(a, a)); nb = math.sqrt(dot(b, b))
    return dot(a, b) / (na * nb)

def top1(text_q, img_embs):
    return max(img_embs.items(), key=lambda kv: cos(text_q, kv[1]))[0]

assert top1([0.9,0.1,0.2],
            {'cat.png':[0.8,0.2,0.1],'dog.png':[0.1,0.9,0.2],'car.png':[0.2,0.1,0.9]}) == 'cat.png'
print(top1([0.9,0.1,0.2],
           {'cat.png':[0.8,0.2,0.1],'dog.png':[0.1,0.9,0.2],'car.png':[0.2,0.1,0.9]}))

def cost(n_images, n_text_tokens, vis=0.01, txt=0.0005):
    return n_images * vis + (n_text_tokens / 1000) * txt

def latency_budget():
    b = {"图像预处理": 50, "视觉编码": 120, "文本生成(8 tokens)": 240, "网络/调度": 30}
    b["总预算"] = sum(v for k, v in b.items())
    return b

assert abs(cost(5, 2000) - 0.051) < 1e-9
print(f"单次调用成本: ${cost(5,2000):.4f}")
print(latency_budget())
